{"path":"/GitHub/link_6aacf81066c081918b61766cfb3f9d27/create_file","args":{"repository_full_name":"oldmangrizzz/dottie","path":"tests/test_boundary_regressions.py","content":""""Regression tests for Dottie evidence and authority primitives."""
import unittest
from dottie_core import Capability, authorize, evidence_record, reconcile_claims

class BoundaryRegressions(unittest.TestCase):
    def test_empty_capability_denies(self):
        self.assertFalse(authorize(Capability("aegis", frozenset()), "read"))

    def test_ungranted_publish_denies(self):
        self.assertFalse(authorize(Capability("aegis", frozenset({"read"})), "publish"))

    def test_blank_source_rejected(self):
        with self.assertRaises(ValueError):
            evidence_record("  ", "content", "verified")

    def test_digest_changes_with_content(self):
        a = evidence_record("source", "original", "verified")
        b = evidence_record("source", "mutated", "verified")
        self.assertNotEqual(a["digest"], b["digest"])

    def test_equal_claims_consistent(self):
        claims = [{"source_id": "a", "value": 1}, {"source_id": "b", "value": 1}]
        self.assertEqual(reconcile_claims(claims)["state"], "consistent")

    def test_conflict_preserves_all_sources(self):
        claims = [{"source_id": "a", "value": "yes"}, {"source_id": "b", "value": "no"}]
        self.assertEqual(reconcile_claims(claims)["sources"], ["a", "b"])
        self.assertEqual(reconcile_claims(claims)["state"], "unresolved")

if __name__ == "__main__":
    unittest.main()
","message":"test: add evidence provenance and authority boundary regressions","branch":"work/dottie-architecture-public-gate"}}

{"path":"/GitHub/link_6aacf81066c081918b61766cfb3f9d27/create_file","args":{"repository_full_name":"oldmangrizzz/dottie","path":"dottie/memory.py","content":""""Persistent, scoped memory for Dottie and independent AEGIS agents.

SQLite is used for durable local storage. Retrieval is always scoped by
both namespace and owner; there is deliberately no unscoped search method.
"""
import json
import sqlite3
from datetime import datetime, timezone

SCOPES = frozenset({
    "dottie-private", "gmri-institutional", "aegis-shared",
    "agent-private", "mission", "evidence", "gev-world"
})
OWNER_SCOPES = frozenset({"dottie-private", "agent-private", "mission"})

class ScopedMemory:
    def __init__(self, path: str):
        self.db = sqlite3.connect(path)
        self.db.execute("""CREATE TABLE IF NOT EXISTS memory (
            scope TEXT NOT NULL, owner TEXT NOT NULL, key TEXT NOT NULL,
            value TEXT NOT NULL, updated_at TEXT NOT NULL,
            PRIMARY KEY (scope, owner, key))""")
        self.db.commit()

    @staticmethod
    def _validate(scope: str, owner: str, key: str):
        if scope not in SCOPES:
            raise ValueError("unknown memory scope")
        if not isinstance(owner, str) or not owner.strip():
            raise ValueError("owner required")
        if not isinstance(key, str) or not key.strip():
            raise ValueError("key required")
        if scope == "dottie-private" and owner != "dottie":
            raise PermissionError("Dottie private memory requires Dottie owner")
        if scope in OWNER_SCOPES and owner == "*":
            raise PermissionError("wildcard owner forbidden")

    def put(self, scope: str, owner: str, key: str, value):
        self._validate(scope, owner, key)
        timestamp = datetime.now(timezone.utc).isoformat()
        with self.db:
            self.db.execute("""INSERT INTO memory VALUES (?, ?, ?, ?, ?)
                ON CONFLICT(scope, owner, key) DO UPDATE SET
                value=excluded.value, updated_at=excluded.updated_at""",
                (scope, owner, key, json.dumps(value), timestamp))

    def get(self, scope: str, owner: str, key: str):
        self._validate(scope, owner, key)
        row = self.db.execute(
            "SELECT value FROM memory WHERE scope=? AND owner=? AND key=?",
            (scope, owner, key)).fetchone()
        return json.loads(row[0]) if row else None

    def close(self):
        self.db.close()
","message":"feat: implement durable scoped memory storage for Dottie and AEGIS","branch":"work/dottie-architecture-public-gate"}}

{"path":"/GitHub/link_6aacf81066c081918b61766cfb3f9d27/create_file","args":{"repository_full_name":"oldmangrizzz/dottie","path":"dottie/evidence.py","content":""""Append-only evidence ledger with source digests and conflict preservation."""
import hashlib
import json
import sqlite3
import time
import uuid

STATUSES = frozenset({"verified", "calculated", "user-reported", "disputed"})

class EvidenceLedger:
    def __init__(self, path):
        self.db = sqlite3.connect(path)
        self.db.execute("""CREATE TABLE IF NOT EXISTS evidence (
            id TEXT PRIMARY KEY, claim_id TEXT NOT NULL, source_id TEXT NOT NULL,
            digest TEXT NOT NULL, status TEXT NOT NULL, value_json TEXT NOT NULL,
            recorded_at REAL NOT NULL)""")
        self.db.execute("CREATE INDEX IF NOT EXISTS evidence_claim_idx ON evidence(claim_id)")
        self.db.commit()

    def append(self, claim_id, source_id, source_content, status, value):
        if not claim_id or not source_id or not isinstance(source_content, (str, bytes)):
            raise ValueError("claim, source and source content required")
        if status not in STATUSES:
            raise ValueError("unsupported evidence status")
        raw = source_content.encode("utf-8") if isinstance(source_content, str) else source_content
        record_id = str(uuid.uuid4())
        with self.db:
            self.db.execute("INSERT INTO evidence VALUES (?,?,?,?,?,?,?)",
                (record_id, claim_id, source_id, hashlib.sha256(raw).hexdigest(),
                 status, json.dumps(value), time.time()))
        return record_id

    def history(self, claim_id):
        if not claim_id:
            raise ValueError("claim required")
        rows = self.db.execute("""SELECT id,source_id,digest,status,value_json,recorded_at
            FROM evidence WHERE claim_id=? ORDER BY recorded_at,id""", (claim_id,)).fetchall()
        return [{"id":r[0], "source_id":r[1], "digest":r[2], "status":r[3],
                 "value":json.loads(r[4]), "recorded_at":r[5]} for r in rows]

    def reconcile(self, claim_id):
        records = self.history(claim_id)
        if not records:
            return {"state": "missing", "records": []}
        distinct = {json.dumps(r["value"], sort_keys=True) for r in records}
        return {"state": "unresolved" if len(distinct) > 1 else "consistent",
                "records": records}

    @staticmethod
    def verify_source(record, content):
        raw = content.encode("utf-8") if isinstance(content, str) else content
        return hashlib.sha256(raw).hexdigest() == record["digest"]

    def close(self):
        self.db.close()
","message":"feat: implement append-only evidence ledger with provenance and conflict tracking","branch":"work/dottie-architecture-public-gate"}}

{"path":"/GitHub/link_6aacf81066c081918b61766cfb3f9d27/create_file","args":{"repository_full_name":"oldmangrizzz/dottie","path":"dottie/runtime.py","content":""""Dottie runtime: authenticated task submission and durable agent execution.

Handlers are registered explicitly by agent identity. Workers execute real
Python callables; no simulated model, Apple, or GEV service is implied.
"""
import sqlite3
from .identity import IdentityStore
from .jobs import JobQueue
from .evidence import EvidenceLedger
from .memory import ScopedMemory

class DottieRuntime:
    def __init__(self, database_path):
        self.identity = IdentityStore(database_path)
        self.jobs = JobQueue(database_path)
        self.evidence = EvidenceLedger(database_path)
        self.memory = ScopedMemory(database_path)
        self.handlers = {}

    def register_agent(self, agent_id, handler):
        if not isinstance(agent_id, str) or not agent_id.strip() or not callable(handler):
            raise ValueError("agent identity and callable handler required")
        if agent_id in self.handlers:
            raise ValueError("agent already registered")
        self.handlers[agent_id] = handler

    def submit(self, user_id, agent_id, payload, idempotency_key):
        if not self.identity.allowed(user_id, "agents:dispatch"):
            raise PermissionError("dispatch permission denied")
        if agent_id not in self.handlers:
            raise LookupError("agent is not registered")
        return self.jobs.submit(agent_id, {"submitted_by": user_id, "input": payload}, idempotency_key)

    def run_next(self):
        job = self.jobs.claim()
        if job is None:
            return None
        try:
            handler = self.handlers.get(job["agent"])
            if handler is None:
                raise LookupError("agent handler unavailable")
            result = handler(job["payload"]["input"])
            self.jobs.finish(job["id"], result)
            return {"id": job["id"], "state": "completed", "result": result}
        except Exception as exc:
            self.jobs.fail(job["id"], str(exc))
            return {"id": job["id"], "state": "failed", "error": str(exc)}

    def close(self):
        self.memory.close()
        self.evidence.close()
        self.jobs.close()
        self.identity.close()
","message":"feat: wire authenticated users, persistent jobs, agents and evidence into runtime","branch":"work/dottie-architecture-public-gate"}}

