{"path":"/GitHub/link_6aacf81066c081918b61766cfb3f9d27/create_file","args":{"repository_full_name":"oldmangrizzz/dottie","path":"dottie/aegis.py","content":""""Canonical independent AEGIS identities.

Identity and ownership persist independently of any execution model or worker.
"""
import sqlite3

COMMANDOS = (
    ("dugan", "Timothy Aloysius Cadwallader Dugan"),
    ("jones", "Gabe Jones"),
    ("morita", "Jim Morita"),
    ("falsworth", "James Montgomery Falsworth"),
    ("dernier", "Jacques Dernier"),
)

class AgentRegistry:
    def __init__(self, path):
        self.db = sqlite3.connect(path)
        self.db.execute("""CREATE TABLE IF NOT EXISTS aegis_agents (
            id TEXT PRIMARY KEY, display_name TEXT NOT NULL,
            commander TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1)""")
        with self.db:
            for agent_id, name in COMMANDOS:
                self.db.execute("""INSERT OR IGNORE INTO aegis_agents
                    (id,display_name,commander,enabled) VALUES (?,?,?,1)""",
                    (agent_id, name, "dottie"))

    def list_agents(self):
        return [{"id": r[0], "name": r[1], "commander": r[2], "enabled": bool(r[3])}
                for r in self.db.execute(
                    "SELECT id,display_name,commander,enabled FROM aegis_agents ORDER BY id")]

    def get(self, agent_id):
        row = self.db.execute("""SELECT id,display_name,commander,enabled
            FROM aegis_agents WHERE id=?""", (agent_id,)).fetchone()
        return ({"id": row[0], "name": row[1], "commander": row[2],
                 "enabled": bool(row[3])} if row else None)

    def close(self):
        self.db.close()
","message":"feat: persist canonical independent Howling Commandos identities","branch":"work/dottie-architecture-public-gate"}}

{"path":"/GitHub/link_6aacf81066c081918b61766cfb3f9d27/create_file","args":{"repository_full_name":"oldmangrizzz/dottie","path":"dottie/memberships.py","content":""""Multi-user AEGIS assignments with per-agent membership and scoped access."""
import sqlite3

MEMBER_ROLES = frozenset({"operator", "collaborator", "observer"})
PERMISSIONS = {
    "operator": frozenset({"dispatch", "read", "write", "manage"}),
    "collaborator": frozenset({"dispatch", "read", "write"}),
    "observer": frozenset({"read"}),
}

class AgentMemberships:
    def __init__(self, database_path):
        self.db = sqlite3.connect(database_path)
        self.db.execute("""CREATE TABLE IF NOT EXISTS aegis_memberships (
            agent_id TEXT NOT NULL,
            user_id TEXT NOT NULL,
            role TEXT NOT NULL,
            PRIMARY KEY(agent_id, user_id),
            FOREIGN KEY(agent_id) REFERENCES aegis_agents(id),
            FOREIGN KEY(user_id) REFERENCES users(id))""")
        self.db.execute("PRAGMA foreign_keys=ON")
        self.db.commit()

    def grant(self, agent_id, user_id, role, granted_by):
        if role not in MEMBER_ROLES:
            raise ValueError("invalid membership role")
        self._require_agent(agent_id)
        self._require_user(user_id)
        if not self._can_manage(granted_by, agent_id):
            raise PermissionError("agent membership management denied")
        with self.db:
            self.db.execute("""INSERT INTO aegis_memberships VALUES (?,?,?)
                ON CONFLICT(agent_id,user_id) DO UPDATE SET role=excluded.role""",
                (agent_id, user_id, role))

    def bootstrap_owner(self, agent_id, owner_id):
        self._require_agent(agent_id)
        row = self.db.execute(
            "SELECT role FROM users WHERE id=? AND active=1", (owner_id,)).fetchone()
        if not row or row[0] != "owner":
            raise PermissionError("only the system owner can bootstrap")
        with self.db:
            self.db.execute("""INSERT OR IGNORE INTO aegis_memberships
                VALUES (?,?,?)""", (agent_id, owner_id, "operator"))

    def revoke(self, agent_id, user_id, revoked_by):
        if not self._can_manage(revoked_by, agent_id):
            raise PermissionError("agent membership management denied")
        with self.db:
            self.db.execute("DELETE FROM aegis_memberships WHERE agent_id=? AND user_id=?",
                            (agent_id, user_id))

    def allowed(self, agent_id, user_id, action):
        row = self.db.execute("""SELECT m.role FROM aegis_memberships m
            JOIN users u ON u.id=m.user_id
            JOIN aegis_agents a ON a.id=m.agent_id
            WHERE m.agent_id=? AND m.user_id=? AND u.active=1 AND a.enabled=1""",
            (agent_id, user_id)).fetchone()
        return bool(row and action in PERMISSIONS[row[0]])

    def members(self, agent_id, requested_by):
        if not self.allowed(agent_id, requested_by, "read"):
            raise PermissionError("membership visibility denied")
        return [{"user_id": uid, "role": role} for uid, role in
                self.db.execute("""SELECT user_id,role FROM aegis_memberships
                    WHERE agent_id=? ORDER BY user_id""", (agent_id,))]

    def _can_manage(self, user_id, agent_id):
        row = self.db.execute("SELECT role FROM users WHERE id=? AND active=1",
                              (user_id,)).fetchone()
        return bool(row and (row[0] == "owner" or
                            self.allowed(agent_id, user_id, "manage")))

    def _require_agent(self, agent_id):
        if not self.db.execute("SELECT 1 FROM aegis_agents WHERE id=?", (agent_id,)).fetchone():
            raise LookupError("unknown agent")

    def _require_user(self, user_id):
        if not self.db.execute("SELECT 1 FROM users WHERE id=? AND active=1", (user_id,)).fetchone():
            raise LookupError("unknown active user")

    def close(self):
        self.db.close()
","message":"feat: add per-agent multi-user membership and role authorization","branch":"work/dottie-architecture-public-gate"}}

{"path":"/GitHub/link_6aacf81066c081918b61766cfb3f9d27/update_file","args":{"repository_full_name":"oldmangrizzz/dottie","path":"dottie/runtime.py","content":""""Integrated local runtime for Dottie and independent agent handlers."""
from .identity import IdentityStore
from .jobs import JobQueue
from .evidence import EvidenceLedger
from .memory import ScopedMemory
from .aegis import AgentRegistry
from .memberships import AgentMemberships

class DottieRuntime:
    def __init__(self, database_path):
        self.identity = IdentityStore(database_path)
        self.jobs = JobQueue(database_path)
        self.evidence = EvidenceLedger(database_path)
        self.memory = ScopedMemory(database_path)
        self.agents = AgentRegistry(database_path)
        self.memberships = AgentMemberships(database_path)
        self.handlers = {}

    def register_agent(self, agent_id, handler):
        if not isinstance(agent_id, str) or not agent_id.strip() or not callable(handler):
            raise ValueError("agent identity and callable handler required")
        if agent_id in self.handlers:
            raise ValueError("agent already registered")
        self.handlers[agent_id] = handler

    def submit(self, user_id, agent_id, payload, idempotency_key):
        if not self.identity.allowed(user_id, "agents:dispatch"):
            raise PermissionError("dispatch permission denied")
        if agent_id not in self.handlers:
            raise LookupError("agent is not registered")
        if not self.memberships.allowed(agent_id, user_id, "dispatch"):
            raise PermissionError("agent membership dispatch denied")
        return self.jobs.submit(agent_id, {"submitted_by": user_id, "input": payload}, idempotency_key)

    def run_next(self):
        job = self.jobs.claim()
        if job is None:
            return None
        try:
            handler = self.handlers.get(job["agent"])
            if handler is None:
                raise LookupError("agent handler unavailable")
            result = handler(job["payload"]["input"])
            self.jobs.finish(job["id"], result)
            return {"id": job["id"], "state": "completed", "result": result}
        except Exception as exc:
            self.jobs.fail(job["id"], str(exc))
            return {"id": job["id"], "state": "failed", "error": str(exc)}

    def close(self):
        self.memberships.close()
        self.agents.close()
        self.memory.close()
        self.evidence.close()
        self.jobs.close()
        self.identity.close()
