{"path":"/GitHub/link_6aacf81066c081918b61766cfb3f9d27/create_file","args":{"repository_full_name":"oldmangrizzz/dottie","branch":"work/dottie-architecture-public-gate","path":"dottie/delegation.py","message":"feat: add consent-bound per-agent delegation with expiry and revocation","content":""""Consent-bound delegated access to one AEGIS agent.

Delegation is not global user impersonation. The account receiving help
controls grants and revocation; no other user's owner role overrides consent.
"""
import json
import sqlite3
import time
import uuid

class Delegations:
    def __init__(self, path):
        self.db = sqlite3.connect(path)
        self.db.execute("""CREATE TABLE IF NOT EXISTS delegations (
            id TEXT PRIMARY KEY, principal TEXT NOT NULL, delegate TEXT NOT NULL,
            agent TEXT NOT NULL, permissions TEXT NOT NULL,
            expires_at REAL NOT NULL, revoked_at REAL)""")
        self.db.commit()

    def grant(self, principal, delegate, agent, permissions, authorized_by, ttl_seconds):
        if authorized_by != principal:
            raise PermissionError("principal must authorize delegation")
        if principal == delegate or ttl_seconds <= 0:
